  select s.id, 'Review 2. Ôn tập Unit 6–10', '{"seed_id":"ta3-gs-review2","kind":"book","book":"Global Success","ref":"Review 2","unit_code":"GS3.P2","unit_title":"Học kì 1 · Unit 6–10","description":"Ôn tập: từ vựng, chữ và mẫu câu Unit 6–10."}'::jsonb, 'review', v_admin, 'Global Success', 1, 74, (select id from public.curriculum_topics where code = 'A3.LANG')
  from public.subjects s where s.code = 'tieng-anh-3' returning id into v_lesson;
end $$;

-- Kiểm tra sau khi nạp: mọi đáp án phải đúng định dạng (kết quả mong đợi: 0)
select count(*) as dap_an_sai_dinh_dang from public.questions qq join public.question_keys k on k.question_id = qq.id join public.lessons l on l.id = qq.lesson_id where l.content ? 'seed_id' and not public.answer_key_is_valid(qq.question_type, k.answer_key);
