  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Lần đầu thấy biển\":\nVừa xuống xe, Na đã nghe tiếng sóng rì rào. Trước mắt em là biển xanh mênh mông, nối liền với bầu trời. Bãi cát trắng mịn, mát lạnh dưới chân. Những con sóng nhỏ nối đuôi nhau xô vào bờ, tung bọt trắng xoá. Na nhặt được một vỏ ốc nhỏ xíu, có những đường vân tím nhạt. Em áp vỏ ốc vào tai và tưởng như nghe thấy biển đang hát.\n\nBãi cát được tả như thế nào?"}'::jsonb, '["trắng mịn, mát lạnh","vàng óng, nóng bỏng","đen sẫm, ẩm ướt"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
