  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Món trứng rán đầu tiên\":\nChủ nhật, Mai xin mẹ cho tự làm món trứng rán. Mẹ hướng dẫn: \"Con đập trứng vào bát, thêm chút muối rồi đánh thật đều.\" Mai cẩn thận làm theo. Khi chảo nóng, mẹ đổ dầu, Mai nhẹ nhàng đổ trứng vào. Trứng sôi xèo xèo, vàng ươm. Mai lật trứng hơi vụng nên miếng trứng bị gãy đôi. Bố vẫn khen: \"Món trứng ngon nhất bố từng ăn!\" Mai sung sướng, hẹn tuần sau sẽ nấu món canh.\n\nCâu \"Mai nhẹ nhàng đổ trứng vào.\" là kiểu câu nào?"}'::jsonb, '["câu nêu hoạt động","câu giới thiệu","câu nêu đặc điểm"]'::jsonb, null, 4, 70, 6, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.03')) returning id into v_q;
