  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Mùa hè của bé Thảo\":\nMùa hè đến, sân nhà Thảo rực đỏ hoa phượng. Thảo có nhiều niềm vui: đọc truyện, tập bơi, chăm sóc mấy chậu hoa của mẹ. Buổi trưa, tiếng ve kêu râm ran như một dàn đồng ca. Chiều chiều, em cùng anh trai đạp xe quanh hồ. Khi những ngày hè sắp hết, Thảo xếp sách vở gọn gàng, tự nhủ: \"Năm học mới, mình sẽ cố gắng hơn!\"\n\nSân nhà Thảo có hoa gì?"}'::jsonb, '["hoa phượng","hoa đào","hoa sữa"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
