  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Con đường đến lớp\":\nNhà Hưng ở cuối làng, cách trường gần hai cây số. Con đường đến lớp quanh co, hai bên là ruộng lúa xanh mướt. Mùa mưa, đường lầy lội, Hưng phải xắn quần, xách dép. Mùa khô, bụi đỏ bám đầy gấu áo. Dù vậy, chưa buổi nào Hưng đi học muộn. Em bảo: \"Đường xa nhưng có các bạn cùng đi, vui lắm!\" Mỗi sáng, tiếng cười nói của nhóm bạn làm con đường như ngắn lại.\n\nHai bên đường đến lớp của Hưng có gì?"}'::jsonb, '["ruộng lúa xanh mướt","nhà cao tầng","rừng thông"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
