  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Bài toán khó\":\nGiờ toán, cô giáo cho cả lớp một bài toán đố. Vy nghĩ mãi chưa ra. Bạn Tâm ngồi cạnh định nhắc bài, nhưng Vy lắc đầu: \"Để tớ tự nghĩ thêm đã!\" Vy vẽ hình ra nháp, thử từng cách. Cuối giờ, Vy giơ tay xin trả lời. Cô giáo mỉm cười: \"Em làm đúng rồi! Cách giải của em rất sáng tạo.\" Vy hiểu rằng tự mình tìm ra lời giải thì vui gấp nhiều lần.\n\nKhi Tâm định nhắc bài, Vy làm gì?"}'::jsonb, '["lắc đầu, muốn tự nghĩ thêm","chép bài của Tâm","bỏ không làm nữa"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
