  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Đôi bàn tay khéo léo\":\nCô giáo lớp em có đôi bàn tay thật khéo. Chỉ với vài tờ giấy màu, cô gấp được những con hạc, bông hoa, chiếc thuyền xinh xắn. Cô dạy chúng em cắt dán bức tranh \"Ngôi trường em yêu\". Bạn nào làm chưa khéo, cô cầm tay chỉ từng nét. Cuối buổi, bức tranh của cả lớp được treo lên bảng. Ôi, đẹp quá! Chúng em reo lên sung sướng.\n\nCâu \"Ôi, đẹp quá!\" là kiểu câu gì?"}'::jsonb, '["câu cảm","câu kể","câu hỏi"]'::jsonb, null, 3, 60, 5, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.02')) returning id into v_q;
