  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Góc sách của lớp 3B\":\nLớp 3B có một góc sách nhỏ do các bạn tự góp. Mỗi bạn mang đến một cuốn sách mình yêu thích. Bạn Đức được bầu làm thủ thư. Đức ghi tên sách vào sổ, dán nhãn cẩn thận. Ai mượn sách, Đức nhắc: \"Cậu nhớ giữ sách sạch đẹp và trả đúng hẹn nhé!\" Nhờ góc sách, giờ ra chơi lớp 3B lúc nào cũng có bạn ngồi say sưa đọc.\n\nSách ở góc sách của lớp 3B từ đâu mà có?"}'::jsonb, '["do các bạn tự góp","do nhà trường mua","do thư viện cho mượn"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
