  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Cây bàng sân trường\":\nGiữa sân trường em có một cây bàng già. Mùa xuân, cây đâm chồi non xanh biếc. Mùa hè, tán lá xoè rộng như chiếc ô che mát cả góc sân. Mùa thu, lá bàng đỏ như ngọn lửa. Mùa đông, cây trụi lá, chỉ còn những cành khẳng khiu. Chúng em yêu cây bàng vì cây như một người bạn lớn, lặng lẽ chứng kiến bao kỉ niệm tuổi học trò.\n\nMùa hè, tán bàng được so sánh với gì?"}'::jsonb, '["chiếc ô","ngọn lửa","người bạn nhỏ"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
