  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chiếc gương của bà\":\nBà nội bị đau chân nên ít khi ra vườn. Bé Nga thương bà lắm. Một buổi sáng, Nga lấy chiếc gương nhỏ, hứng ánh nắng rồi chiếu vào phòng bà. Vệt nắng vàng nhảy nhót trên tường, trên tấm chăn. Bà cười móm mém: \"Cháu bà mang cả mùa xuân vào nhà rồi!\" Từ đó, sáng nào Nga cũng làm \"người đưa nắng\" cho bà.\n\nBà nói \"Cháu bà mang cả mùa xuân vào nhà rồi!\" ý bà muốn nói gì?"}'::jsonb, '["Bà rất vui, thấy ấm áp nhờ việc làm của cháu","Mùa xuân đã đến thật","Bà muốn ra vườn"]'::jsonb, null, 3, 60, 5, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.02')) returning id into v_q;
