  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Buổi tối ở nhà Bảo\":\nTối nào nhà Bảo cũng có \"giờ trò chuyện\". Cả nhà tắt ti vi, ngồi quanh ấm trà của ông. Mỗi người kể một chuyện trong ngày: mẹ kể chuyện ở bệnh viện, bố kể chuyện công trường, Bảo kể chuyện lớp học. Ông thường dặn: \"Có chuyện vui thì cùng cười, có chuyện buồn thì cùng chia sẻ.\" Bảo thích giờ trò chuyện nhất trong ngày.\n\nTrong \"giờ trò chuyện\", cả nhà Bảo làm gì?"}'::jsonb, '["tắt ti vi, ngồi kể chuyện trong ngày","cùng xem phim","mỗi người làm việc riêng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
