  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Cây cầu tre của bản\":\nBản Pác Bó nằm bên kia con suối. Mùa lũ, nước dâng cao, các bạn nhỏ không sang trường được. Ông Lý rủ mọi người cùng làm cầu. Người chặt tre, người buộc lạt, người khiêng đá kê chân cầu. Chỉ sau ba ngày, cây cầu tre chắc chắn đã bắc qua suối. Ông Lý dặn các cháu: \"Các cháu hãy đi cẩn thận và giữ gìn cây cầu nhé!\"\n\nVì sao mùa lũ các bạn nhỏ không sang trường được?"}'::jsonb, '["vì nước suối dâng cao","vì trường đóng cửa","vì đường bị sạt lở"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
