  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Cô thợ may đầu ngõ\":\nĐầu ngõ nhà em có tiệm may nhỏ của cô Hạnh. Cô đo, cắt, khâu nhanh thoăn thoắt. Những tấm vải qua tay cô trở thành chiếc áo, chiếc váy vừa vặn. Mùa đông năm ngoái, cô may hai mươi chiếc áo ấm tặng các bạn nhỏ vùng cao. Em hỏi: \"Sao cô làm nhiều áo thế?\" Cô cười: \"Để các bạn ấy đến lớp không bị lạnh, cháu ạ.\"\n\nCô Hạnh làm nghề gì?"}'::jsonb, '["thợ may","giáo viên","bác sĩ"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
