  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Người canh ngọn đèn\":\nTrên hòn đảo nhỏ giữa biển có một ngọn hải đăng. Chú Toàn là người canh đèn ở đó. Đêm nào chú cũng lên đỉnh tháp kiểm tra, lau sạch mặt kính. Ánh đèn quét một vòng sáng trên mặt biển, chỉ đường cho tàu thuyền. Có đêm giông bão, chú thức trắng để giữ cho đèn luôn sáng. Ngư dân gọi ngọn hải đăng là \"người bạn của biển đêm\".\n\nNgọn hải đăng ở đâu?"}'::jsonb, '["trên hòn đảo nhỏ giữa biển","trên đỉnh núi","giữa thành phố"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
